// Do not edit. Change the spec and run `npm run gen`.

import type { ReactNode } from "react";

/** The frame of a dashboard or admin app: a sidebar of navigation that folds down to icons, a top bar with search and actions, an account menu, and the page. On a phone, or in any narrow space, the sidebar becomes a menu that slides in. */
export interface DashboardShellSpecProps {
  /**
   * The navigation as groups of items. An item may hold one level of sub-items.
   */
  navigation: import("../sidebar/nav").NavGroup[];
  /**
   * The id of the page you are on. It is marked as the current page (aria-current) and its parent opens.
   */
  currentId?: string;
  /**
   * Your logo or product name, at the top of the sidebar and the title of the phone menu.
   */
  brand?: ReactNode;
  /**
   * The organisation or workspace shown at the top of the sidebar, with its logo and a second line such as the plan. Replaces brand there.
   */
  team?: import("../sidebar/nav").ShellTeam;
  /**
   * Other workspaces to switch to. With two or more the team becomes a menu.
   */
  teams?: import("../sidebar/nav").ShellTeam[];
  /**
   * Called with the workspace the person chose.
   */
  onTeamChange?: (team: import("../sidebar/nav").ShellTeam) => void;
  /**
   * The signed-in person: shown at the bottom of the sidebar with an account menu.
   */
  user?: import("../sidebar/nav").ShellUser;
  /**
   * Content for the left of the top bar, such as breadcrumbs or the page title.
   */
  header?: ReactNode;
  /**
   * Controls for the right of the top bar, such as a theme switch or a Create button.
   */
  actions?: ReactNode;
  /**
   * Shows a search button in the top bar and calls this when it is pressed, e.g. to open a command palette.
   */
  onSearch?: () => void;
  /**
   * Text and accessible name of the search button.
   * @default "Search"
   */
  searchLabel?: string;
  /**
   * Accessible name of the navigation.
   * @default "Main navigation"
   */
  label?: string;
  /**
   * Text of the skip link, the first thing a keyboard user can press.
   * @default "Skip to main content"
   */
  skipLabel?: string;
  /**
   * Called with the item when one is chosen. Items without an href use this to do their work.
   */
  onNavigate?: (item: import("../sidebar/nav").NavItem) => void;
  /**
   * Draw items as your router's link. Return the link with the given className and children; call onClick when chosen. Without it, items with an href are plain links.
   */
  renderLink?: (props: { item: import("../sidebar/nav").NavItem; className: string; children: import("react").ReactNode; isCurrent: boolean; onClick: () => void }) => import("react").ReactNode;
  /**
   * Controlled: whether the sidebar is folded down to icons.
   */
  isCollapsed?: boolean;
  /**
   * Start folded down.
   * @default false
   */
  defaultCollapsed?: boolean;
  /**
   * Called when the person folds or opens the sidebar. Save it if you want it remembered.
   */
  onCollapsedChange?: (collapsed: boolean) => void;
  /**
   * The page.
   */
  children: ReactNode;
}

export const dashboardShellDefaults = {
  searchLabel: "Search",
  label: "Main navigation",
  skipLabel: "Skip to main content",
  defaultCollapsed: false,
} as const;

export const dashboardShellMeta = {
  "name": "DashboardShell",
  "version": "0.1.0",
  "status": "experimental",
  "role": "navigation"
} as const;
